s="form-control input-sm"><?php foreach(['pending','in_transit','arrived','completed','cancelled'] as $status): ?><option value="<?=$status?>" <?=$row['status']===$status?'selected':''?>><?=$status?></option><?php endforeach;?></select> <label><input type="checkbox" name="arrival_confirmed"> Arrived</label> <input name="outcome" placeholder="Outcome" class="form-control input-sm"><input name="outcome_notes" placeholder="Outcome notes" class="form-control input-sm"><button class="btn btn-xs btn-primary">Update</button><?php endif; ?></form></td><?php elseif($kind==='users'): ?><td><form method="post"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$row[$pk]?>"><button class="btn btn-xs btn-warning">Toggle active</button></form></td><?php elseif($kind==='notifications'): ?><td><?php if(!$row['is_read']): ?><form method="post"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['csrf_token'])?>"><input type="hidden" name="id" value="<?=$row[$pk]?>"><button class="btn btn-xs btn-primary">Mark read</button></form><?php else: ?>Read<?php endif; ?><?php if(($row['reference_type']??'')==='symptom_report'): ?><a class="btn btn-xs btn-info" href="maternal_intelligence">Review cases</a><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="10" class="text-center text-muted">No records yet.</td></tr><?php endif; ?></tbody></table></div></div></section>
